"""Render an interactive, self-contained HTML view of the JSON report."""
from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from ..schema import json_safe


def write_html_report(report: dict[str, Any], path: Path) -> None:
    payload = json.dumps(json_safe(report), ensure_ascii=False, allow_nan=False).replace("<", "\\u003c")
    html = """<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Experiment comparison</title><style>
:root{font-family:Inter,system-ui,sans-serif;color:#182230;background:#f4f6f8}body{margin:0}.wrap{max-width:1440px;margin:auto;padding:24px}h1{margin:0 0 4px}small{color:#667085}.controls,.card{background:white;border:1px solid #d0d5dd;border-radius:10px;padding:16px;margin:16px 0}.controls{display:flex;gap:12px;align-items:center}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px}.stat{background:#f8fafc;border-radius:8px;padding:12px}.stat b{display:block;font-size:1.4rem}table{border-collapse:collapse;width:100%;font-size:.9rem}th,td{text-align:left;padding:8px;border-bottom:1px solid #eaecf0}th{position:sticky;top:0;background:#fff}.scroll{max-height:460px;overflow:auto}canvas{width:100%;height:320px;border:1px solid #eaecf0;border-radius:8px}.unavailable{color:#b42318}
</style></head><body><div class="wrap"><h1>Experiment comparison</h1><small id="generated"></small>
<div class="controls"><label for="experiment">Experiment</label><select id="experiment"></select></div><div id="summary" class="grid"></div>
<div class="card"><h2>Objective curves</h2><canvas id="curve" width="1200" height="320"></canvas></div>
<div class="card"><h2>Parameter dynamics</h2><label for="parameter">Tensor</label> <select id="parameter"></select><p><small>RMS midpoint estimate over the logged W&B history coordinates.</small></p><canvas id="parameter-curve" width="1200" height="320"></canvas></div>
<div class="card"><h2>Trials</h2><div class="scroll"><table><thead><tr><th>Trial</th><th>State</th><th>Objective</th><th>Best coordinate</th><th>Last</th><th>Ingredient logging</th></tr></thead><tbody id="trials"></tbody></table></div></div>
<div class="card"><h2>Largest parameter-distribution changes</h2><div class="scroll"><table><thead><tr><th>Tensor</th><th>Role</th><th>Observations</th><th>Median CDF distance</th><th>Median RMS change</th></tr></thead><tbody id="parameters"></tbody></table></div></div>
<div class="card"><h2>Per-ingredient metrics</h2><label for="ingredient">Series</label> <select id="ingredient"></select><canvas id="ingredient-curve" width="1200" height="320"></canvas><div class="scroll"><table><thead><tr><th>Split</th><th>Metric</th><th>Index</th><th>Ingredient</th><th>Trials</th><th>Mean last value</th></tr></thead><tbody id="ingredients"></tbody></table></div></div>
<div class="card"><h2>Inter-experiment comparisons</h2><pre id="inter"></pre></div><div class="card"><h2>Limitations</h2><ul id="limitations"></ul></div></div>
<script id="report-data" type="application/json">__REPORT__</script><script>
const report=JSON.parse(document.getElementById('report-data').textContent);const fmt=v=>v===null||v===undefined?'—':(typeof v==='number'?Number(v).toPrecision(5):String(v));const esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
document.getElementById('generated').textContent=`Generated ${report.generated_at} · schema ${report.schema_version}`;const select=document.getElementById('experiment');report.experiments.forEach((experiment,index)=>{const option=document.createElement('option');option.value=index;option.textContent=experiment.name;select.appendChild(option)});
function drawCurves(experiment){const canvas=document.getElementById('curve'),ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);const curves=experiment.trials.filter(t=>t.curve.status==='available').map(t=>({number:t.number,points:t.curve.points}));if(!curves.length){ctx.fillText('No curve data',20,30);return}const xs=curves.flatMap(c=>c.points.map(p=>p.coordinate)),ys=curves.flatMap(c=>c.points.map(p=>p.value));const minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);const pad=36;const x=v=>pad+(v-minX)/(maxX-minX||1)*(canvas.width-2*pad),y=v=>canvas.height-pad-(v-minY)/(maxY-minY||1)*(canvas.height-2*pad);ctx.strokeStyle='#d0d5dd';ctx.strokeRect(pad,pad,canvas.width-2*pad,canvas.height-2*pad);curves.forEach((curve,index)=>{ctx.beginPath();ctx.strokeStyle=`hsl(${index*47%360} 62% 45% / .42)`;curve.points.forEach((point,i)=>i?ctx.lineTo(x(point.coordinate),y(point.value)):ctx.moveTo(x(point.coordinate),y(point.value)));ctx.stroke()});ctx.fillStyle='#475467';ctx.fillText(fmt(minY),2,canvas.height-pad);ctx.fillText(fmt(maxY),2,pad);ctx.fillText(fmt(minX),pad,canvas.height-8);ctx.fillText(fmt(maxX),canvas.width-pad,canvas.height-8)}
function parameterSessions(experiment){return Object.values(experiment.wandb.trials||{}).flatMap(trial=>trial.sessions||[]).filter(session=>session.status==="available")}
function populateParameters(experiment){const target=document.getElementById("parameter"),previous=target.value,keys=[...new Set(parameterSessions(experiment).flatMap(session=>Object.keys(session.series||{})))].sort();target.innerHTML=keys.map(key=>`<option value="${esc(key)}">${esc(key)}</option>`).join("");if(keys.includes(previous))target.value=previous}
function drawParameter(experiment){const canvas=document.getElementById("parameter-curve"),ctx=canvas.getContext("2d"),key=document.getElementById("parameter").value;ctx.clearRect(0,0,canvas.width,canvas.height);const trajectories=parameterSessions(experiment).filter(session=>session.series[key]).map(session=>session.series[key].trajectory);if(!trajectories.length){ctx.fillText("No parameter trajectory available",20,30);return}const points=trajectories.flatMap(series=>series.map((sample,index)=>({x:sample.history_record_clocks.epoch??sample.history_record_clocks["trainer/global_step"]??sample.history_record_clocks._step??index,y:sample.rms_midpoint_estimate})));const xs=points.map(point=>point.x),ys=points.map(point=>point.y),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys),pad=36;const x=value=>pad+(value-minX)/(maxX-minX||1)*(canvas.width-2*pad),y=value=>canvas.height-pad-(value-minY)/(maxY-minY||1)*(canvas.height-2*pad);ctx.strokeStyle="#d0d5dd";ctx.strokeRect(pad,pad,canvas.width-2*pad,canvas.height-2*pad);trajectories.forEach((series,index)=>{ctx.beginPath();ctx.strokeStyle=`hsl(${index*97%360} 65% 42%)`;series.forEach((sample,i)=>{const px=sample.history_record_clocks.epoch??sample.history_record_clocks["trainer/global_step"]??sample.history_record_clocks._step??i,py=sample.rms_midpoint_estimate;i?ctx.lineTo(x(px),y(py)):ctx.moveTo(x(px),y(py))});ctx.stroke()});ctx.fillStyle="#475467";ctx.fillText(fmt(minY),2,canvas.height-pad);ctx.fillText(fmt(maxY),2,pad)}
function populateIngredients(experiment){const target=document.getElementById("ingredient"),previous=target.value,series=experiment.ingredient_analysis.series||[];target.innerHTML=series.map((item,index)=>`<option value="${index}">${esc(item.split+"/"+item.metric+"/"+item.label_index+" "+(item.label||""))}</option>`).join("");if([...target.options].some(option=>option.value===previous))target.value=previous}
function drawIngredient(experiment){const canvas=document.getElementById("ingredient-curve"),ctx=canvas.getContext("2d"),item=(experiment.ingredient_analysis.series||[])[Number(document.getElementById("ingredient").value)||0];ctx.clearRect(0,0,canvas.width,canvas.height);if(!item||!item.trajectory.length){ctx.fillText("No per-ingredient trajectory available",20,30);return}const points=item.trajectory,xValues=points.map(point=>point.coordinate),yValues=points.map(point=>point.mean),minX=Math.min(...xValues),maxX=Math.max(...xValues),minY=Math.min(...yValues),maxY=Math.max(...yValues),pad=36;const x=value=>pad+(value-minX)/(maxX-minX||1)*(canvas.width-2*pad),y=value=>canvas.height-pad-(value-minY)/(maxY-minY||1)*(canvas.height-2*pad);ctx.strokeStyle="#d0d5dd";ctx.strokeRect(pad,pad,canvas.width-2*pad,canvas.height-2*pad);ctx.beginPath();ctx.strokeStyle="#2563eb";points.forEach((point,index)=>index?ctx.lineTo(x(point.coordinate),y(point.mean)):ctx.moveTo(x(point.coordinate),y(point.mean)));ctx.stroke();ctx.fillStyle="#475467";ctx.fillText(fmt(minY),2,canvas.height-pad);ctx.fillText(fmt(maxY),2,pad)}
function render(){const experiment=report.experiments[Number(select.value)||0],summary=experiment.summary;document.getElementById('summary').innerHTML=[['Trials',summary.trials],['Eligible',summary.eligible_trials],['Study selected trial',summary.study_selected_trial?.number],['Selected objective',summary.study_selected_trial?.objective],['W&B sessions',experiment.parameter_analysis.sessions],['Ingredient metrics',experiment.ingredient_analysis.status]].map(([k,v])=>`<div class="stat"><span>${esc(k)}</span><b>${esc(fmt(v))}</b></div>`).join('');document.getElementById('trials').innerHTML=experiment.trials.map(t=>`<tr><td>${t.number}</td><td>${esc(t.state)}</td><td>${esc(fmt(t.objective))}</td><td>${esc(fmt(t.curve.best?.coordinate))}</td><td>${esc(fmt(t.curve.last?.value))}</td><td>${esc(t.ingredient_logging_status)}</td></tr>`).join('');document.getElementById('parameters').innerHTML=(experiment.parameter_analysis.largest_distribution_drifts||[]).map(t=>`<tr><td>${esc(t.key)}</td><td>${esc(t.role)}</td><td>${t.observations}</td><td>${esc(fmt(t.normalized_cdf_distance_median))}</td><td>${esc(fmt(t.rms_relative_change_median))}</td></tr>`).join('')||'<tr><td colspan="5" class="unavailable">No W&B histogram analysis requested or available.</td></tr>';document.getElementById('ingredients').innerHTML=(experiment.ingredient_analysis.series||[]).map(t=>`<tr><td>${esc(t.split)}</td><td>${esc(t.metric)}</td><td>${t.label_index}</td><td>${esc(t.label)}</td><td>${t.trials}</td><td>${esc(fmt(t.last_value_mean))}</td></tr>`).join('')||'<tr><td colspan="6" class="unavailable">Per-ingredient logging unavailable.</td></tr>';populateParameters(experiment);populateIngredients(experiment);drawCurves(experiment);drawParameter(experiment);drawIngredient(experiment)}
select.addEventListener('change',render);document.getElementById("parameter").addEventListener("change",()=>drawParameter(report.experiments[Number(select.value)||0]));document.getElementById("ingredient").addEventListener("change",()=>drawIngredient(report.experiments[Number(select.value)||0]));render();document.getElementById('inter').textContent=JSON.stringify(report.inter_experiment,null,2);document.getElementById('limitations').innerHTML=report.limitations.map(item=>`<li>${esc(item)}</li>`).join('');
</script></body></html>""".replace("__REPORT__", payload)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(html, encoding="utf-8")
